// Block (composition) — a commerce product preview, with a primary add action when one is given.
// Card, Badge, Button, and Stack own their look; this Block only arranges them.
import type { ReactNode, Ref } from "react";
import { AspectRatio } from "../layouts/AspectRatio";
import { Badge } from "../components/Badge";
import { Button } from "../components/Button";
import { Card, CardMedia } from "../components/Card";
import { Stack } from "../layouts/Stack";
import "./ProductCard.css";

export interface ProductCardProps {
  title: string;
  price: string;
  /** The price before the discount, struck through under `price` (a factory or list price). */
  originalPrice?: string;
  image?: ReactNode;
  badge?: string;
  /** The add action. Without it the card draws no Button: a browsing card whose whole tile leads on. */
  onAdd?: () => void;
  addLabel?: string;
  /**
   * The picture band, which must contrast with the ground the CARD sits on: `well` (default) a grey
   * plate for a card on a white page, `plain` no plate for a card on a grey `Band`, where the
   * cut-out sits contained on the card's own white surface.
   *
   * @default "well"
   */
  mediaVariant?: "well" | "plain";
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

export function ProductCard({
  title,
  price,
  originalPrice,
  image,
  badge,
  onAdd,
  addLabel = "Add to cart",
  mediaVariant = "well",
  className,
  ref,
}: ProductCardProps) {
  return (
    <Card
      ref={ref}
      className={className ? `sd-productcard ${className}` : "sd-productcard"}
    >
      {/* The picture is the card's top, a band edge to edge (CardMedia, a direct child so it can meet
          the card's corners). 4 / 3 so a row of product tiles keeps one silhouette regardless of the
          source image; the ratio is passed, AspectRatio being the Layout that owns it. CardMedia's
          well plates a cut-out render and contains an `img` whole. */}
      {image && (
        <CardMedia variant={mediaVariant}>
          <AspectRatio ratio={4 / 3} className="sd-productcard__media">
            {image}
          </AspectRatio>
        </CardMedia>
      )}
      <Stack gap="small" className="sd-productcard__content">
        <Stack gap="x-small" className="sd-productcard__detail">
          <Stack direction="row" align="center" gap="x-small" wrap className="sd-productcard__heading">
            <>
              <h3 className="sd-productcard__title sd-type-title-medium">{title}</h3>
            </>
            {badge && <Badge>{badge}</Badge>}
          </Stack>
          <>
            <p className="sd-productcard__price sd-type-body-medium-emphasized">{price}</p>
          </>
          {originalPrice && (
            <p className="sd-productcard__original">
              <s className="sd-type-caption-medium">{originalPrice}</s>
            </p>
          )}
        </Stack>
        {onAdd && (
          <Button variant="primary" onPress={onAdd}>
            {addLabel}
          </Button>
        )}
      </Stack>
    </Card>
  );
}

/* ProductCard.css — .sd-productcard (Block)
   Arrangement only: fills its cell and provides a bounded media slot. The height is left to the row:
   a flex or grid row stretches its items to the tallest, and a `height: 100%` here would opt the card
   OUT of that stretch (a percentage against a row with no definite height), so one card came out
   short in a row of four. */
.sd-productcard {
  width: 100%;
}

/* The box, the ratio and the clipping come from AspectRatio (the Layout primitive); this rule
   keeps only what is this Block's own arrangement — centring artwork that is not an img/svg/video
   inside the frame (Media fills and fits those itself). */
.sd-productcard__media {
  place-items: center;
}

.sd-productcard__title,
.sd-productcard__price,
.sd-productcard__original {
  margin: 0;
}

/* The struck price is a supporting line under the price it was cut to (text colour row 4). */
.sd-productcard__original {
  color: var(--sd-color-text-muted);
}

/* In a row of tiles the cards stretch to the tallest, so the content fills the card and the detail
   takes the slack: every Add button sits on the card's bottom edge, whatever the name's length. */
.sd-productcard__content {
  flex: 1;
}

.sd-productcard__detail {
  flex: 1;
}
